import{_ as t,a as r,o as a,a4 as o}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Customer","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/shop/customer/index.md","filePath":"api/graphql-api/shop/customer/index.md","lastUpdated":1783327468000}'),d={name:"api/graphql-api/shop/customer/index.md"};function s(i,e,n,h,l,u){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="customer" tabindex="-1">Customer <a class="header-anchor" href="#customer" aria-label="Permalink to &quot;Customer&quot;">​</a></h1><p>The Customer menu is the customer&#39;s account area — registering and signing in, managing the profile and address book, viewing past orders, invoices, shipments, and downloadable products, and managing their own reviews. It backs every &quot;My Account&quot; screen on the storefront.</p><h2 id="authentication-session" tabindex="-1">Authentication &amp; session <a class="header-anchor" href="#authentication-session" aria-label="Permalink to &quot;Authentication &amp; session&quot;">​</a></h2><p>A customer registers, then logs in to receive a <strong>Bearer token</strong>. That token is sent on every account operation (and is the same token used by Cart, Checkout, Wishlist, and Compare). The token can be verified, and logging out invalidates it. Forgot Password starts the password-reset flow by email.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Profile</strong> — read, update, or delete the signed-in customer&#39;s account.</li><li><strong>Orders</strong> — list the customer&#39;s orders, view one order in detail, view its shipments, and cancel or reorder an order.</li><li><strong>Invoices</strong> — list invoices, view one, and download an invoice PDF.</li><li><strong>Downloadable products</strong> — list the customer&#39;s purchased downloadable products and download a file.</li><li><strong>Addresses</strong> — list, create, update, and delete saved addresses (the address book).</li><li><strong>Reviews</strong> — read the reviews the customer has written.</li></ul><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><h3 id="profile-session" tabindex="-1">Profile &amp; session <a class="header-anchor" href="#profile-session" aria-label="Permalink to &quot;Profile &amp; session&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/mutations/customer-registration.html">Customer Registration</a></td><td><code>createCustomer</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/customer-login.html">Customer Login</a></td><td><code>tokenCreate</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/customer-verify-token.html">Customer Verify Token</a></td><td><code>verifyToken</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/customer-logout.html">Customer Logout</a></td><td><code>logout</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/forgot-password.html">Forgot Password</a></td><td><code>forgotPassword</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-customer-profile.html">Get Customer Profile</a></td><td><code>customer</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/update-customer-profile.html">Update Customer Profile</a></td><td><code>updateCustomerProfile</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/delete-customer-profile.html">Delete Customer Profile</a></td><td><code>deleteCustomerProfile</code> mutation</td></tr></tbody></table><h3 id="orders" tabindex="-1">Orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;Orders&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/get-customer-orders.html">Get Customer Orders</a></td><td><code>customerOrders</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-customer-order.html">Get Customer Order</a></td><td><code>customerOrder(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-customer-order-shipments.html">Get Customer Order Shipments</a></td><td><code>customerOrderShipments</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-customer-order-shipment.html">Get Customer Order Shipment</a></td><td><code>customerOrderShipment(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/cancel-customer-order.html">Cancel Customer Order</a></td><td><code>cancelOrder</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/reorder-customer-order.html">Reorder Customer Order</a></td><td><code>reorder</code> mutation</td></tr></tbody></table><h3 id="invoices" tabindex="-1">Invoices <a class="header-anchor" href="#invoices" aria-label="Permalink to &quot;Invoices&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/get-customer-invoices.html">Get Customer Invoices</a></td><td><code>customerInvoices</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-customer-invoice.html">Get Customer Invoice</a></td><td><code>customerInvoice(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/download-invoice.html">Download Invoice</a></td><td><code>downloadInvoice</code> query</td></tr></tbody></table><h3 id="downloadable-products" tabindex="-1">Downloadable products <a class="header-anchor" href="#downloadable-products" aria-label="Permalink to &quot;Downloadable products&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/get-customer-downloadable-products.html">Get Downloadable Products</a></td><td><code>downloadableProducts</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-customer-downloadable-product.html">Get Downloadable Product</a></td><td><code>downloadableProduct(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/download-downloadable-product.html">Download Downloadable Product</a></td><td><code>downloadDownloadableProduct</code> query</td></tr></tbody></table><h3 id="addresses" tabindex="-1">Addresses <a class="header-anchor" href="#addresses" aria-label="Permalink to &quot;Addresses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/get-customer-addresses.html">Get Customer Addresses</a></td><td><code>addresses</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/create-customer-address.html">Create Customer Address</a></td><td><code>createAddress</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/update-customer-address.html">Update Customer Address</a></td><td><code>updateAddress</code> mutation</td></tr><tr><td><a href="/api/graphql-api/shop/mutations/delete-customer-address.html">Delete Customer Address</a></td><td><code>deleteAddress</code> mutation</td></tr></tbody></table><h3 id="reviews" tabindex="-1">Reviews <a class="header-anchor" href="#reviews" aria-label="Permalink to &quot;Reviews&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operation</th><th>GraphQL field</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/shop/queries/get-customer-reviews.html">Get Customer Reviews</a></td><td><code>customerReviews</code> query</td></tr><tr><td><a href="/api/graphql-api/shop/queries/get-customer-review.html">Get Customer Review</a></td><td><code>customerReview(id:)</code> query</td></tr></tbody></table><p>Registration, Login, and Forgot Password are public (storefront key only); every other operation requires a customer Bearer token — see <a href="/api/graphql-api/authentication.html">Authentication</a>.</p>',20)]))}const m=t(d,[["render",s]]);export{p as __pageData,m as default};
